using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Edits the text of a message (or a text of a game message). Returns the edited message after the edit is completed on the server side
    /// </summary>
    public Task<TdLib.TdApi.Objects.Message> EditMessageTextAsync(long chatId = default, long messageId = default, ReplyMarkup replyMarkup = default, InputMessageContent inputMessageContent = default)
    {

           using var activity =  StartCallActivity("EditMessageTextAsync", typeof(EditMessageText).FullName ?? "EditMessageTextAsync");

           try
           {
             return client.EditMessageTextAsync(chatId, messageId, replyMarkup, inputMessageContent);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
